test:
// pysssss.ShowText — `this.widgets.length = isConvertedWidget` truncation, plus
// the ComfyWidgets["STRING"] + inputEl.readOnly readouts it rebuilds each run.
//
// Run this file against BOTH the original and the converted source.
//
//   equivalence  must pass on both — the conversion changed no behaviour
//   fix          must FAIL on the original and PASS on the converted source
//
// equivalence: executing renders one widget per string, named text_<index> from
//              the current widget count, and re-executing rebuilds them.
// fix 1:       shrinking the readout leaves no stale ids in the widget render
//              order. Assigning `widgets.length` never reached
//              `removeNodeWidgetOrder`, and `setNodeWidgetOrder` reconciles
//              rather than drops — so text_1/text_2 stayed in the store's order
//              forever and Nodes 2.0 kept rendering widgets that were gone.
// fix 2:       the readouts are non-editable through the published `disabled`
//              property instead of `inputEl.readOnly`, a deprecated alias the
//              Vue node renderer never consults.
import { beforeAll, describe, expect, it } from 'vitest'

import { LGraph } from '@/lib/litegraph/src/LGraph'
import { LGraphNode } from '@/lib/litegraph/src/LGraphNode'
import { applyDefExtensions, useComfyApi } from '@/platform/nodeApi/comfyApi'
import { useCanvasStore } from '@/renderer/core/canvas/canvasStore'
import { app } from '@/scripts/app'
import { useExtensionStore } from '@/stores/extensionStore'
import { useWidgetValueStore } from '@/stores/widgetValueStore'

const TYPE = 'ShowText|pysssss'
const DEF = {
  name: TYPE,
  display_name: 'Show Text',
  category: 'utils/string',
  output: ['STRING'],
  output_name: ['STRING'],
  input: { required: { text: ['STRING', { forceInput: true }] } }
}

class ShowText extends LGraphNode {
  constructor() {
    super(TYPE)
  }
}

const graph = new LGraph()

beforeAll(async () => {
  // Both dispatch paths run: the original registered a legacy
  // `beforeRegisterNodeDef`, the converted source a `comfy.defs.extend`. Only
  // one of them has anything to apply, so this file is source-agnostic.
  useCanvasStore().currentGraph = graph
  useComfyApi(() => graph)
  for (const extension of useExtensionStore().extensions) {
    await extension.beforeRegisterNodeDef?.(
      ShowText as never,
      DEF as never,
      app
    )
  }
  applyDefExtensions(ShowText, DEF)
})

function newNode(): LGraphNode {
  const node = new ShowText()
  // The original reads `this.inputs?.[0].widget`, which throws on a node with
  // no inputs — the real def gives ShowText a forced `text` input.
  node.addInput('text', 'STRING')
  graph.add(node)
  return node
}

const execute = (node: LGraphNode, text: string[]) =>
  node.onExecuted?.({ text } as never)

const widgetNames = (node: LGraphNode) => node.widgets?.map((w) => w.name) ?? []

describe('pysssss.ShowText', () => {
  describe('equivalence — must pass before and after', () => {
    it('renders one widget per string, in order', () => {
      const node = newNode()
      execute(node, ['alpha', 'beta', 'gamma'])

      expect(widgetNames(node)).toEqual(['text_0', 'text_1', 'text_2'])
      expect(node.widgets?.map((w) => w.value)).toEqual([
        'alpha',
        'beta',
        'gamma'
      ])
    })

    it('flattens a nested list and drops a leading empty entry', () => {
      const node = newNode()
      execute(node, ['', ['one', 'two']] as never)

      expect(node.widgets?.map((w) => w.value)).toEqual(['one', 'two'])
    })

    it('rebuilds rather than appends across executions', () => {
      const node = newNode()
      execute(node, ['a', 'b', 'c'])
      execute(node, ['only'])

      expect(widgetNames(node)).toEqual(['text_0'])
      expect(node.widgets?.[0].value).toBe('only')
    })
  })

  describe('fix — must fail before, pass after', () => {
    it('leaves no stale widget ids in the render order after shrinking', () => {
      const node = newNode()
      execute(node, ['a', 'b', 'c'])
      execute(node, ['only'])

      const live = new Set(node.widgets?.map((w) => w.widgetId))
      const order = useWidgetValueStore().getNodeWidgetIds(
        graph.rootGraph.id,
        node.id
      )

      expect(order.filter((id) => !live.has(id))).toEqual([])
    })

    it('marks the readouts disabled rather than faking read-only on inputEl', () => {
      const node = newNode()
      execute(node, ['a', 'b'])

      expect(node.widgets?.map((w) => w.disabled)).toEqual([true, true])
    })
  })
})
